import {createPaymentsUI} from './payments-ui.js';
import {TOURNAMENT_COVERS,tournamentPrize,localDateTime} from './tournaments.js';
import {pieceSVG} from './pieces.js';
import {createTrustUI} from './trust-ui.js';
import {TRUST_NOTICE} from './trust.js';
import {userHandle,isOnline,related,socialCount} from './social.js';
import {boardPosition,positionStatus,moveSound,drawReason,capturedPieces,gameOutcome} from './board-feedback.js';
import {unlockSound,toggleSound,soundEnabled,soundVolume,setSoundVolume,playSound} from './sound.js';
import { POOLS, getRating, poolFor } from './rating.js';
import { LEVELS } from './computer.js';
import { Chess } from 'chess.js';
import { createClient } from '@supabase/supabase-js';
import { initialState, applyCommand } from './domain.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={play:'<path d="m9 5 11 7-11 7z"/>',trophy:'<path d="M8 3h8v6a4 4 0 0 1-8 0zM8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4M12 13v7m-4 1h8"/>',wallet:'<path d="M20 8V5H5a3 3 0 0 0 0 6h15v10H5a3 3 0 0 1-3-3V8m18 5h-6v5h6m-3-3h1"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6zm-4 9 3 3 5-6"/>',chart:'<path d="M4 3v18h17M8 16v-5m5 5V7m5 9V4"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 4c3 0 4 2 4 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'};
const icon=n=>n==='trophy'?`<svg viewBox="0 0 24 24" aria-hidden="true"><defs><linearGradient id="trophy-metal"><stop stop-color="#94601c"/><stop offset=".3" stop-color="#ffe9a0"/><stop offset=".6" stop-color="#ce922b"/><stop offset="1" stop-color="#ffdc75"/></linearGradient></defs><path fill="none" stroke="#b27d25" stroke-width="2" d="M7 5H3v3c0 4 3 5 6 5m8-8h4v3c0 4-3 5-6 5"/><path fill="url(#trophy-metal)" stroke="#e6b650" stroke-width=".6" d="M6 2h12v7a6 6 0 0 1-5 6v4h4v3H7v-3h4v-4a6 6 0 0 1-5-6z"/><path fill="none" stroke="#fff0b9" opacity=".65" d="M8 4v5c0 2 1 3 2 3"/></svg>`:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.play}</svg>`;
const credits=n=>`${((n||0)/100).toLocaleString('pt-BR',{maximumFractionDigits:2})} cr`;
const label={open:'Aberto',matched:'Em jogo',registration:'Inscrições abertas',running:'Em andamento',finished:'Concluído',cancelled:'Cancelado',pending:'Aceite pendente',playing:'Em jogo',review:'Em homologação',active:'Ativa',suspended:'Suspensa',banned:'Banida'};
let setupHtml='',setupRenderedHtml='';
let config={},client,session,online=false,tab='lobby',state,actor={id:'demo-you',admin:false},selected=null,practice=null,gameId=null,filter='all',busy=false;
let peopleQuery='',peopleFilter='all',profilePhoto=null,sandraPhoto=null;
let movesExpanded=true;
let historyPly=null,feedbackKey=null,feedbackMoves=0,feedbackResult=null;
let computerWorker=null,thinking=false,boardFlipped=false,engineGeneration=0,lastPresence=0,queueMode='all',rankingPool='blitz',renderedTab=null,renderedActor=null;
const trust=createTrustUI({state:()=>state,actor:()=>actor,config:()=>config,modal,send,request:trustRequest,render,esc,name,toast});
const payments=createPaymentsUI({actor:()=>online?actor:null,config:()=>config,request:trustRequest,modal,esc,toast});
function wallet(){const legacy=legacyWallet(),cut=legacy.indexOf('<div class="wallet-cards">');return legacy.slice(0,cut)+payments.render()+'<details class="panel"><summary>Créditos anteriores e extrato</summary>'+legacy.slice(cut)+'</details>'; }
async function trustRequest(action,body,query={}){if(!session)throw Error('Entre na sua conta.');const qs=new URLSearchParams({action,...Object.fromEntries(Object.entries(query).filter(([,v])=>v!==undefined))});const response=await fetch('/api/index?'+qs,{method:body?'POST':'GET',headers:{'Content-Type':'application/json',Authorization:`Bearer ${session.access_token}`},...(body?{body:JSON.stringify(body)}:{})});const data=await response.json();if(!response.ok)throw Error(data.error||'Não foi possível concluir.');if(data.state){state=data.state;actor=data.actor;render();}return data;}
function seed(){let s=initialState();const people=[['demo-you','Você',1200],['demo-luiza','Luiza R.',1320],['demo-pedro','Pedro M.',1180],['demo-ana','Ana C.',1410],['demo-admin','Administrador',1500]];for(const [uid,name,rating]of people){s=applyCommand(s,{id:uid,admin:false},{id:crypto.randomUUID(),type:'register',payload:{name}});s.players[uid].rating=rating;s=applyCommand(s,{id:uid},{id:crypto.randomUUID(),type:'demo_credit'});}for(const [uid,stake,minutes]of [['demo-luiza',1000,5],['demo-pedro',2000,3],['demo-ana',500,10]])s=applyCommand(s,{id:uid},{id:crypto.randomUUID(),type:'challenge_create',payload:{stake,minutes}});s=applyCommand(s,{id:'demo-admin',admin:true},{id:'demo-tournament',type:'tournament_create',payload:{name:'Copa de abertura',capacity:4,entry:1000,minutes:5,minRating:0,maxRating:2000,startsAt:Date.now()+86400000,requireVerified:false,cameraFinal:false}});return s;}
function loadDemo(){try{const saved=JSON.parse(localStorage.getItem('arena-demo-v1'));state=saved?.version===1?saved:seed();}catch{state=seed();}online=false;actor={id:'demo-you',admin:false};}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4500);}
async function api(command){const response=await fetch('/api/index'+(command?'':'?action=state'),{method:command?'POST':'GET',headers:{'Content-Type':'application/json',...(session?{Authorization:`Bearer ${session.access_token}`}:{})},...(command?{body:JSON.stringify(command)}:{})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Falha na conexão.');return data;}
async function send(type,payload={}){if(busy)return;if(config.configured&&!online&&!['register'].includes(type)){loginForm();return false;}busy=true;try{const command={id:crypto.randomUUID(),type,payload};if(online){const result=await api(command);state=result.state;actor=result.actor;}else{state=applyCommand(state,actor,command);localStorage.setItem('arena-demo-v1',JSON.stringify(state));}selected=null;render();syncMatchDialog();return true;}catch(e){if(type==='tournament_create'&&$('#tournament-error'))$('#tournament-error').textContent=e.message;toast(e.message);return false;}finally{busy=false;}}
function name(uid){return esc(state.players[uid]?.bot?'Sandra - computador':state.players[uid]?.name||'Jogador');}
function avatar(uid){const p=state.players[uid];const photo=p?.avatarPath&&config.supabaseUrl?config.supabaseUrl+'/storage/v1/object/public/arena-avatars/'+p.avatarPath:null;return `<span class="avatar hue${(uid||'').length%4}">${photo?`<img src="${esc(photo)}" alt="Foto de ${name(uid)}" loading="lazy" decoding="async">`:p?.bot?'<img src="/computer-avatar.svg" alt="Sandra, computador">':esc((p?.name||'?').slice(0,1))}</span>`;}
function boardAvatar(g,color){if(!practice)return avatar(color==='w'?g.white:g.black);if(g.computer&&color!==g.humanColor)return '<span class="avatar computer-avatar"><img src="/computer-avatar.svg" alt="Avatar do computador Arena"></span>';return `<span class="avatar" aria-label="${g.computer?'Você':'Peças '+(color==='w'?'brancas':'pretas')}">${g.computer?'♙':color==='w'?'♔':'♚'}</span>`;}
function playerRating(uid,pool='blitz'){if(state.players[uid]?.bot)return '';const r=getRating(state.players[uid],pool);return `<span class="player-rating" title="Rating ${esc(pool)}${r.games<10||r.deviation>110?' provisório':''}">(${Math.round(r.rating)}${r.games<10||r.deviation>110?'?':''})</span>`;}
function playerLink(uid,pool='blitz'){return `<button class="player-link" data-action="player-profile" data-id="${uid}">${name(uid)} ${playerRating(uid,pool)}</button>`;}

function badge(text,type=''){return `<span class="badge ${type}">${esc(text)}</span>`;}
function modal(html){$('#modal').dataset.match='false';$('#modal').innerHTML=`<button class="close" data-close aria-label="Fechar">×</button>${html}`;$('#modal').showModal();}
function shell(){const me=state.players[actor?.id];$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#lobby"><img src="/icon.svg" alt="">arena<span>xadrez</span></a><div class="nav-label">SEU PRÓXIMO LANCE</div><nav>${[['lobby','play','Jogar'],['tournaments','trophy','Torneios'],['ranking','chart','Ranking'],['community','users','Jogadores'],['wallet','wallet','Carteira'],['fairplay','shield','Fair play'],['my-games','play','Meus confrontos'],...(actor?.admin?[['admin','users','Administração']]:[])].map(([v,i,t])=>`<button class="nav ${tab===v||v==='tournaments'&&tab==='tournament-create'?'active':''}" data-tab="${v}">${icon(i)}<span>${t}</span>${v==='community'&&socialCount(state,actor?.id)?`<i aria-label="Novas solicitações">${socialCount(state,actor?.id)}</i>`:''}${v==='tournaments'?`<i aria-label="${tournamentCount()} campeonatos disponíveis">${tournamentCount()}</i>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="small-panel">${icon('shield')}<strong>Jogue com confiança.</strong><p>Regras claras.<br>Competição justa.</p><button class="text-btn" data-tab="fairplay">Conheça o fair play ↗</button></div><button class="profile" data-action="profile">${avatar(actor?.id)}<span><b>${me?name(actor.id)+' '+playerRating(actor.id):'Visitante'}</b><small>${online?'Conta online':config.configured?'Visitante · entre para jogar online':'Perfil local'}</small></span><span>⋯</span></button></div></aside><main><header><div class="breadcrumb">Arena <span>/</span> ${esc({lobby:'Jogar',tournaments:'Torneios',ranking:'Ranking',community:'Jogadores e amizades',wallet:'Carteira',fairplay:'Fair play',admin:'Administração',board:'Mesa de jogo'}[tab]||'Jogar')}</div><div class="header-right"><span class="status-dot"></span><span>${online?'Online':config.configured?'Entre para jogar online':'Modo local'}</span><button class="balance" data-tab="wallet">${icon('wallet')}${credits(me?.available)}</button><button class="button small" data-action="${online?'logout':'login'}">${online?'Sair':'Entrar'}</button></div></header><div class="content" id="content"></div><footer>ARENA XADREZ <span>Cada lance conta.</span><a href="#fairplay">Regras e privacidade</a></footer></main><nav class="mobile-nav">${[['lobby','play','Jogar'],['tournaments','trophy','Torneios'],['community','users','Jogadores'],['wallet','wallet','Carteira'],['fairplay','shield','Fair play']].map(([v,i,t])=>`<button data-tab="${v}" class="${tab===v||v==='tournaments'&&tab==='tournament-create'?'active':''}">${icon(i)}${t}${v==='community'&&socialCount(state,actor?.id)?` <b class="nav-count">${socialCount(state,actor?.id)}</b>`:''}${v==='tournaments'?` <b class="nav-count">${tournamentCount()}</b>`:''}</button>`).join('')}</nav>`;}
function miniBoard(){const board=new Chess();return `<div class="hero-board" aria-hidden="true">${board.board().flat().map((p,i)=>`<div class="mini-square ${(Math.floor(i/8)+i%8)%2?'dark':'light'}">${p?piece(p):''}</div>`).join('')}</div>`;}
const glyph={wk:'♚',wq:'♛',wr:'♜',wb:'♝',wn:'♞',wp:'♟',bk:'♚',bq:'♛',br:'♜',bb:'♝',bn:'♞',bp:'♟'};
function piece(p){return `<span class="piece ${p.color==='w'?'white-piece':'black-piece'}">${pieceSVG(p)}</span>`;}
function lobby(){const offers=state.challenges.filter(c=>!c.target&&(queueMode==='all'||(queueMode==='free'?c.stake===0:c.stake>0))&&c.status==='open'&&(!c.expiresAt||c.expiresAt>Date.now())&&(filter==='all'||c.minutes===Number(filter)));return `${playModes()}<section class="hero"><div class="hero-copy"><div class="eyebrow"><span></span> PARA QUEM PENSA À FRENTE</div><h1>Seu talento.<br>Seu próximo <em>desafio.</em></h1><p>Encontre seu adversário, entre na mesa<br>e faça cada lance valer.</p><div class="hero-actions"><button class="button primary" data-action="create-challenge">${icon('plus')} Criar desafio</button><button class="button ghost" data-tab="tournaments">Explorar torneios ${icon('arrow')}</button></div><div class="hero-note">${icon('shield')} Valores e taxa visíveis antes do aceite</div></div><div class="hero-art">${miniBoard()}<div class="floating-tag">♞ <span>Uma boa partida<br><b>começa com você.</b></span></div></div></section><div class="stat-strip"><div>${icon('play')}<span><b>${state.challenges.filter(c=>c.status==='open'&&(!c.expiresAt||c.expiresAt>Date.now())).length}</b> desafios abertos</span></div><div>${icon('trophy')}<span><b>${state.tournaments.filter(t=>t.status==='registration').length}</b> torneios com inscrições</span></div><div>${icon('users')}<span><b>${Object.keys(state.players).length}</b> perfis ${config.configured?'cadastrados':'de demonstração'}</span></div><div>${icon('shield')}<span>Partidas <b>com fair play</b></span></div></div><section class="lobby-grid"><div><div class="section-heading"><div><div class="eyebrow">ESCOLHA SUA MESA</div><h2>Desafios abertos <span class="count">${offers.length}</span></h2></div><button class="text-btn" data-action="create-challenge">Criar desafio +</button></div><div class="filters queue-filters">${[['all','Todas as mesas'],['free','Grátis'],['stake','Com entrada']].map(([v,t])=>`<button data-queue="${v}" class="${queueMode===v?'selected':''}">${t}</button>`).join('')}</div><div class="filters">${[['all','Todos'],[1,'Bullet · 1 min'],[3,'Blitz · 3 min'],[5,'Blitz · 5 min'],[10,'Rápido · 10 min']].map(([v,t])=>`<button data-filter="${v}" class="${String(filter)===String(v)?'selected':''}">${t}</button>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>JOGADOR / RATING</th><th>RITMO</th><th>ENTRADA</th><th>PRÊMIO LÍQUIDO</th><th></th></tr></thead><tbody>${offers.length?offers.map(c=>`<tr><td><div class="player-cell">${avatar(c.creator)}<span>${playerLink(c.creator,poolFor(c.minutes,c.increment))}<small>${Math.round(getRating(state.players[c.creator],poolFor(c.minutes,c.increment)).rating)} ${state.players[c.creator].ratingVerified?'· Verificado':'· Não verificado'}</small></span></div></td><td><span class="time-pill">${icon('clock')}${c.minutes} + ${c.increment||0}</span></td><td><b>${c.stake===0?'Grátis':credits(c.stake)}</b></td><td class="prize">${credits(c.stake*2-Math.floor(c.stake*2*c.feeBps/10000))}<small>Taxa ${c.feeBps/100}%</small></td><td><button class="button outline small" data-action="${c.creator===actor?.id?'cancel-challenge':'accept-challenge'}" data-id="${c.id}">${c.creator===actor?.id?'Cancelar':'Aceitar'} ${icon('arrow')}</button></td></tr>`).join(''):'<tr><td colspan="5" class="empty">Nenhum desafio neste ritmo. Crie a próxima mesa.</td></tr>'}</tbody></table></div><div class="table-note">${icon('shield')} O saldo fica reservado até a homologação do resultado.</div></div><aside class="right-rail"><div class="tournament-promo"><div class="promo-top">${icon('trophy')}${badge('INSCRIÇÕES ABERTAS','green')}</div><div class="eyebrow">SEU PRÓXIMO TROFÉU</div><h3>A competição<br>começa aqui.</h3><p>Enfrente jogadores da sua faixa e avance até a grande final.</p><div class="promo-line"><span>Formato</span><b>Mata-mata</b></div><div class="promo-line"><span>Empate</span><b>Revanche</b></div><button class="button primary" data-tab="tournaments">Ver torneios ${icon('arrow')}</button></div><button class="practice-card" data-action="practice"><span class="practice-knight">♞</span><span><b>Aqueça seu jogo</b><small>Tabuleiro livre no mesmo aparelho</small></span>${icon('arrow')}</button></aside></section>`;}
function ratingResult(g){if(!g.poolRatingApplied)return '';return `<div class="panel"><h3>Rating ${esc(g.pool)}</h3>${[g.white,g.black].map(u=>{const r=g.ratingResults?.[u],d=g.ratingChanges?.[u]||0;return `<div class="promo-line"><span>${name(u)}</span><b>${r?`${r.before} → ${r.after}`:Math.round(getRating(state.players[u],g.pool).rating)} (${d>0?'+':''}${d})</b></div>`;}).join('')}<p class="muted">Atualização pelo resultado contra outro jogador. Treino contra o computador não altera o rating.</p></div>`;}
function myGames(){const games=state.games.filter(g=>[g.white,g.black].includes(actor?.id));return games.length?`<section class="my-games">${games.slice().reverse().map(g=>`<button class="game-row" data-game="${g.id}"><span>${name(g.white)} <small>×</small> ${name(g.black)}</span>${badge(label[g.status])}<span>${g.ratingChanges?.[actor?.id]!==undefined?`Rating ${g.ratingChanges[actor.id]>0?'+':''}${g.ratingChanges[actor.id]} · `:''}Abrir mesa →</span></button>`).join('')}</section>`:'';}
function myGamesPage(){return `<div class="page-heading"><div><div class="eyebrow">SUAS PARTIDAS</div><h1>Meus confrontos</h1><p>Abra suas mesas e acompanhe partidas, resultados e torneios.</p></div></div>${myGames()||`<div class="panel empty">${online?'Você ainda não tem confrontos. Escolha um ritmo para jogar.':'Entre na sua conta para acompanhar seus confrontos online.'}<button class="button primary" data-action="${online?'quick-match':'login'}">${online?'Jogar online':'Entrar'}</button></div>`}`;}
function tournaments(){return `<div class="page-heading"><div><div class="eyebrow">AVANCE A CADA VITÓRIA</div><h1>Torneios da Arena</h1><p>Inscreva-se, aceite o confronto e conquiste seu lugar na final.</p></div>${actor?.admin?'<button class="button primary" data-action="create-tournament">+ Criar torneio</button>':!online?'<button class="button outline" data-action="login">Entrar para organizar</button>':''}</div><div class="tournament-grid">${state.tournaments.map(t=>`<article class="tournament-card"><div class="tournament-cover cover-${esc(t.cover||'gold')}" role="img" aria-label="Capa ${esc(TOURNAMENT_COVERS.find(c=>c.id===(t.cover||'gold'))?.name||'do torneio')}">${t.coverPath?`<img class="uploaded-cover" src="${esc(config.supabaseUrl)}/storage/v1/object/public/arena-avatars/${esc(t.coverPath)}" alt="Capa do torneio">`: ''}<span>ARENA XADREZ</span></div><div class="tournament-card-head">${icon('trophy')}${badge(label[t.status],'green')}</div><h2>${esc(t.isTest?t.name.replace(/\s+(?:de\s+)?teste\b/gi,''):t.name)}</h2>${t.sandra?'<p><b>Inclui Sandra - computador.</b> Ao se inscrever, você aceita essa participação. Partidas contra Sandra não alteram o rating.</p>':''}<p>${new Date(t.startsAt).toLocaleString('pt-BR')} · ${t.minutes} + 0</p><div class="card-stats"><div><small>INSCRIÇÃO</small><b>${credits(t.entry)}</b></div><div><small>${t.economics==='fixed'?'PRÊMIO FIXO':t.prizeGuarantee?'PRÊMIO GARANTIDO':'PRÊMIO ATUAL'}</small><b class="prize">${credits(tournamentPrize(t))}</b></div></div>${actor?.admin&&t.economics==='fixed'?`<p class="admin-finances">Arrecadação: ${credits(t.entry*t.players.length)} · Resultado após prêmio: ${credits(t.entry*t.players.length-t.fixedPrize)}</p>`:''}<div class="capacity"><span style="width:${new Set(t.players).size/t.capacity*100}%"></span></div><div class="promo-line"><span>${new Set(t.players).size}/${t.capacity} inscritos</span><span>Rating ${t.minRating}–${t.maxRating}</span></div><p class="muted">${t.requireVerified?'Rating verificado obrigatório':'Rating não verificado permitido'}${t.cameraFinal?' · Câmera obrigatória na final (infraestrutura pendente)':''}</p>${t.status==='registration'?`<button class="button ${t.players.includes(actor?.id)?'outline':'primary'} full" data-action="${t.players.includes(actor?.id)?'leave-tournament':'join-tournament'}" data-id="${t.id}">${t.players.includes(actor?.id)?'Cancelar inscrição':'Participar do torneio'}</button>`:t.status==='running'&&t.economics==='fixed'&&t.players.includes(actor?.id)&&state.games.filter(g=>g.tournament===t.id&&[g.white,g.black].includes(actor?.id)).at(-1)?.status==='finished'&&state.games.filter(g=>g.tournament===t.id&&[g.white,g.black].includes(actor?.id)).at(-1)?.winner!==actor?.id&&!(t.reentryQueue||[]).includes(actor?.id)?`<button class="button primary full" data-action="reenter-tournament" data-id="${t.id}">Nova inscrição · ${credits(t.entry)}</button><p>Nova pontuação começa em zero. Entrada na próxima rodada.</p>`:t.winner?`<p>Campeão: <b>${name(t.winner)}</b></p>`:''}${actor?.admin&&t.status==='registration'?`<div class="button-row"><button class="button small" data-action="start-tournament" data-id="${t.id}">Iniciar torneio</button><button class="text-btn" data-action="cancel-tournament" data-id="${t.id}">Cancelar</button></div>`:''}${t.scores?`<details><summary>Classificação do campeonato</summary>${Object.entries(t.scores).sort((a,b)=>b[1]-a[1]).map(([u,score])=>`<p>${name(u)} · ${score} pontos</p>`).join('')}</details>`:''}<div class="bracket">${state.games.filter(g=>g.tournament===t.id).map(g=>`<button data-game="${g.id}"><small>Rodada ${g.round} · ${label[g.status]}</small>${name(g.white)} × ${name(g.black)}${g.winner?' → '+name(g.winner):''}</button>`).join('')}</div></article>`).join('')||'<div class="empty panel">Ainda não há torneios cadastrados.</div>'}</div>`;}
function legacyWallet(){const me=state.players[actor?.id];return `<div class="page-heading"><div><div class="eyebrow">CONTROLE EM CADA MOVIMENTO</div><h1>Sua carteira</h1><button class="button outline small" data-action="profile">Meu perfil</button><p>Gerencie seu saldo e acompanhe suas movimentações.</p></div></div><div class="wallet-cards"><article class="panel"><small>SALDO DISPONÍVEL</small><h2>${credits(me?.available)}</h2><div class="button-row"><button class="button primary" disabled title="Disponível após a ativação dos pagamentos">Recarregar saldo</button><button class="button outline" disabled title="Disponível após a ativação dos pagamentos">Sacar</button></div><p class="muted">Recargas e saques em breve. Os créditos existentes não são conversíveis em reais.</p></article><article class="panel"><small>SALDO RESERVADO</small><h2>${credits(me?.reserved)}</h2><p>Comprometido em desafios e torneios.</p></article><article class="panel"><small>COMO FUNCIONA</small><p>O aceite reserva os valores dos dois jogadores. A homologação libera o prêmio com a taxa combinada no desafio.</p></article></div><h2>Extrato</h2><div class="table-wrap"><table><thead><tr><th>DATA</th><th>OPERAÇÃO</th><th>DISPONÍVEL</th><th>RESERVADO</th></tr></thead><tbody>${state.ledger.filter(e=>e.user===actor?.id).slice().reverse().map(e=>`<tr><td>${new Date(e.at).toLocaleString('pt-BR')}</td><td>${esc({demo_credit:'Créditos de demonstração',challenge_hold:'Reserva de desafio',challenge_release:'Devolução de desafio',match_settlement:'Liquidação de confronto',match_prize:'Prêmio de confronto',tournament_hold:'Inscrição em torneio',tournament_release:'Devolução de inscrição',tournament_settlement:'Liquidação de torneio',tournament_prize:'Prêmio de torneio',tournament_prize_hold:'Reserva de prêmio garantido',tournament_prize_release:'Devolução de garantia'}[e.type]||e.type)}</td><td>${e.available>0?'+':''}${credits(e.available)}</td><td>${e.reserved>0?'+':''}${credits(e.reserved)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Entre na conta para ver seu extrato.</td></tr>'}</tbody></table></div>`;}
function tournamentCount(){return state.tournaments.filter(t=>t.status==='running'||t.status==='registration'&&t.startsAt>Date.now()).length;}
function ranking(){const players=Object.values(state.players).filter(p=>p.status==='active'&&!p.bot).sort((a,b)=>getRating(b,rankingPool).rating-getRating(a,rankingPool).rating);return `<div class="page-heading"><div><div class="eyebrow">CADA LANCE CONTA</div><h1>Ranking de jogadores</h1><p>Acompanhe sua posição em cada ritmo. Seu rating evolui nas partidas válidas contra outros jogadores; o símbolo ? indica um rating provisório. Partidas contra o computador não alteram seus pontos.</p></div></div><div class="filters">${POOLS.map(pool=>`<button data-pool="${pool}" class="${rankingPool===pool?'selected':''}">${{bullet:'Bullet',blitz:'Blitz',rapid:'Rápido',classical:'Clássico'}[pool]}</button>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>POSIÇÃO</th><th>JOGADOR</th><th>RATING</th><th>PARTIDAS</th><th>VITÓRIAS</th><th>DERROTAS</th></tr></thead><tbody>${players.map((p,i)=>{const r=getRating(p,rankingPool);return `<tr><td>#${i+1}</td><td><div class="player-cell">${avatar(p.id)}<span>${playerLink(p.id,rankingPool)}<small>@${esc(userHandle(p))}</small></span></div></td><td><b>${Math.round(r.rating)}${r.games<10||r.deviation>110?' ?':''}</b><small>Incerteza ±${Math.round(r.deviation)}</small></td><td>${r.games}</td><td>${r.wins}</td><td>${r.losses}</td></tr>`;}).join('')}</tbody></table></div>${state.players[actor?.id]?.ratingHistory?.length?`<h2>Seu histórico recente</h2><div class="panel">${state.players[actor.id].ratingHistory.filter(h=>h.pool===rankingPool).slice(-15).reverse().map(h=>`<div class="promo-line"><span>${new Date(h.at).toLocaleString('pt-BR')}</span><b>${Math.round(h.rating)} (${h.change>0?'+':''}${h.change})</b></div>`).join('')||'Sem partidas neste ritmo.'}</div>`:''}`;}
function fairplay(){return `<div class="page-heading"><div><div class="eyebrow">O RESPEITO TAMBÉM FAZ PARTE DO JOGO</div><h1>Uma Arena mais justa.</h1><p>Jogue com respeito, siga as regras e dispute cada partida com seus próprios lances.</p></div></div><div class="info-grid">${[['shield','Jogue limpo','O uso de motores de xadrez, extensões de assistência, ajuda de outras pessoas ou dispositivos para escolher lances é proibido. Fraudes comprovadas podem resultar em suspensão ou banimento.'],['chart','Rating e identidade','Cada torneio informa sua faixa de rating e os requisitos de participação. Use uma única conta e forneça informações verdadeiras.'],['users','Resultados e premiação','Resultados podem passar por revisão antes da liberação do prêmio. Em caso de denúncia, os valores permanecem reservados até a conclusão da análise.'],['play','Revisão de fair play','A Arena analisa partidas e denúncias para proteger a competição. As decisões consideram o histórico e o contexto; o jogador pode solicitar revisão.'],['clock','Em caso de empate','O confronto continua em uma nova partida, com as cores invertidas e os valores reservados. Em torneios, o vencedor avança para a próxima rodada.'],['shield','Respeito entre jogadores','Respeite seus adversários. Assédio, combinação de resultados, contas duplicadas e manipulação de rating violam as regras da Arena.']].map(([i,t,p])=>`<article class="panel">${icon(i)}<h2>${t}</h2><p>${p}</p></article>`).join('')}</div><article class="panel legal"><h2>Regras e privacidade</h2><p>Seu perfil, suas partidas e seu histórico são usados para oferecer jogos online, rankings e recursos sociais. Recargas e saques ainda não estão disponíveis. Os créditos existentes não são conversíveis em reais.</p><details><summary>Identidade e fiscalização</summary><p>Quando disponíveis e exigidas para a competição, a verificação de identidade e a fiscalização por câmera são informadas antes da participação e dependem de consentimento. Envie documentos somente pelo formulário seguro da Arena. O formulário informa os dados solicitados, quem poderá acessá-los e os prazos de retenção.</p><p>A fiscalização por câmera utiliza imagens periódicas privadas, sem áudio. O envio de imagens e as condições para jogar são apresentados antes da ativação.</p></details><details><summary>Integridade das partidas</summary><p>Com seu consentimento, podemos registrar saída da página, perda de foco e recursos de extensão visíveis durante partidas. Não acessamos outras abas nem enumeramos extensões instaladas. Esses sinais são avaliados com o contexto da partida antes de qualquer penalidade.</p></details>${!config.configured?'<button class="button outline" data-action="reset-demo">Limpar partidas locais</button>':''}</article>`;}
function fairPlayPanel(){return `<section class="panel"><h2>Triagem automática de fair play</h2><p>O servidor avalia várias partidas, exclui aberturas, respostas forçadas e análises insuficientes. Estes indicadores são heurísticas experimentais para revisão, não uma probabilidade de trapaça. Abertura de caso bloqueia liberação do prêmio. Nenhum jogador é banido apenas por precisão ou saída da aba.</p>${Object.entries(state.fairPlayProfiles||{}).map(([u,r])=>`<div class="promo-line"><span>${name(u)} · ${r.status==='insufficient_sample'?'Amostra insuficiente':r.status==='review_required'?'Revisão necessária':'Nenhuma regra acionada'}</span><small>${r.positions} posições elegíveis · ${r.games} partidas · ${r.opponents} adversários · perda média ${r.averageLoss??'—'} cp${r.ratingContext?.underestimatedRating?' · Rating possivelmente subestimado (contexto auxiliar)':''}</small></div>`).join('')||'<p>Aguardando amostras analisadas.</p>'}${(state.fairPlayCases||[]).filter(c=>c.status==='open').map(c=>`<article class="panel"><h3>Caso ${esc(c.id.slice(0,8))} · ${name(c.user)}</h3><p>${esc(c.version)} · ${c.summary.positions} posições · ${c.summary.games} partidas · ${c.summary.agreement}% de coincidências elegíveis</p><p>Indicadores: ${c.summary.signals.map(esc).join(', ')}</p><button class="button outline small" data-action="fairplay-review" data-id="${c.id}">Registrar conclusão e recurso</button></article>`).join('')}</section>`;}
function administration(){return `<div class="page-heading"><div><div class="eyebrow">CONTROLE DA ARENA</div><h1>Administração</h1><p>${online?'Acesso verificado pelo servidor.':'Simulador administrativo local. Não altera contas reais.'}</p></div></div><div class="admin-grid"><form id="settings-form" class="panel"><h2>Taxas e análise</h2><h3>Sandra - computador</h3><p>Skill 20, sem redução de força. Busca de 1 s por lance no servidor; força limitada pelos recursos disponíveis. Sempre identificada como bot, sem alterar o rating humano.</p><label class="check"><input type="checkbox" name="sandraChallenges" ${state.settings.sandraChallenges?'checked':''}> Habilitar Sandra nos desafios com aceite explícito</label><label class="check"><input type="checkbox" name="sandraTournaments" ${state.settings.sandraTournaments?'checked':''}> Permitir Sandra em novos torneios identificados</label><label class="check"><input type="checkbox" name="automatedFairPlay" ${state.settings.automatedFairPlay!==false?'checked':''}> Triagem automática e retenção de prêmios em revisão</label><label class="check"><input type="checkbox" name="identityRequired" ${state.settings.requireIdentityForStake?'checked':''} ${config.trustConfigured?'':'disabled'}> Exigir identidade aprovada para entrada e prêmio</label><label class="check"><input type="checkbox" name="cameraStake" ${state.settings.cameraForStake?'checked':''} ${config.trustConfigured?'':'disabled'}> Exigir câmera fiscalizada em mesas com entrada</label><label class="check"><input type="checkbox" name="integrityConsent" ${state.settings.requireIntegrityConsent?'checked':''}> Exigir aceite dos sinais de integridade</label><label>Taxa da plataforma (%)<input type="number" name="fee" min="0" max="30" step="0.1" value="${state.settings.feeBps/100}" required></label><label class="check"><input type="checkbox" name="analysis" ${state.settings.analysisEnabled?'checked':''}> Ativar análise privada Stockfish a cada lance</label><label class="check"><input type="checkbox" name="autoSettlement" ${state.settings.autoSettlement?'checked':''}> Creditar prêmio e comissão automaticamente após a análise</label><p class="muted">Denúncias, análise incompleta ou contas restritas impedem a liberação automática. A análise ocorre no servidor após os lances. É evidência para revisão humana e não causa banimento automático. Não mostra sugestões aos jogadores.</p><button class="button primary">Salvar configuração</button></form><article class="panel"><h2>Avatar da Sandra</h2><form id="sandra-avatar-form"><div class="profile-photo">${avatar('arena-sandra')}<span>Sandra · computador</span></div><label>Escolher imagem<input id="sandra-avatar-file" type="file" accept="image/jpeg,image/png,image/webp" ${online?'':'disabled'}></label><p id="sandra-avatar-status">JPEG, PNG ou WebP. Recorte central automático. Máximo 5 MB.</p><button class="button outline" type="submit" ${online?'':'disabled'}>Salvar avatar da Sandra</button><button class="text-btn" type="button" data-action="sandra-avatar-remove" ${online?'':'disabled'}>Restaurar avatar padrão</button></form><h2>Saldo da Sandra</h2><p>${credits(state.players['arena-sandra']?.available||0)} disponíveis · ${credits(state.players['arena-sandra']?.reserved||0)} reservados. Saldo separado da receita da plataforma.</p><form id="sandra-fund"><label>Transferir da minha carteira<input name="amount" type="number" min="1" max="1000" value="10" required></label><button class="button outline">Abastecer Sandra</button></form><h2>Receita da plataforma</h2><h3>${credits(state.platform?.balance||0)}</h3><p>Receitas creditadas automaticamente na carteira administrativa. Recargas e saques serão liberados após a ativação dos pagamentos.</p><h2>Integrações</h2>${[['Supabase',online?'Conectado':'Pendente — organização nova'],['Pagamentos Pix','Não integrado'],['Lichess OAuth / partidas','Não integrado'],['Stockfish privado',config.analysisWorkerConfigured?'Integrado · '+(state.settings.analysisEnabled?'ativado':'desativado pelo admin'):'Indisponível'],['Identidade / CPF',config.trustConfigured?'Revisão manual disponível':'Coleta bloqueada — configure criptografia'],['Câmera / fiscalização',config.trustConfigured?'Quadros privados e revisão manual':'Pendente configuração segura'],['Dinheiro real','Desativado']].map(([a,b])=>`<div class="promo-line"><span>${a}</span>${badge(b)}</div>`).join('')}</article></div>${trust.adminPanel()}${fairPlayPanel()}<h2>Análises privadas</h2><div class="panel"><p>${state.games.reduce((n,g)=>n+(g.analysis||[]).filter(a=>a.status==='pending').length,0)} pendentes · ${state.games.reduce((n,g)=>n+(g.analysis||[]).filter(a=>a.status==='complete').length,0)} concluídas · ${state.games.reduce((n,g)=>n+(g.analysis||[]).filter(a=>a.status==='error').length,0)} com falha</p><button class="button outline small" data-action="analysis-retry">Reprocessar falhas</button> <button class="button outline small" data-action="analysis-test">Testar Stockfish com e4</button>${(state.analysisTests||[]).map(a=>`<p>Teste e4: ${a.status==='complete'?`concluído · ${esc(a.engine)} · profundidade ${a.depth}`:a.status==='pending'?'processando':'falha — reative o teste após revisar o servidor'}</p>`).join('')}${state.games.filter(g=>g.fairPlay).map(g=>`<p>Mesa ${esc(g.id.slice(0,8))}: ${Object.entries(g.fairPlay).map(([u,r])=>`${name(u)} · ${r.positions} posições · ${r.engineMatches} coincidências · perda média ${r.averageLoss} cp`).join(' / ')}</p>`).join('')}<small>Coincidência de lances não prova trapaça. Revise contexto e histórico antes de restringir uma conta.</small></div><h2>Jogadores</h2><div class="table-wrap"><table><thead><tr><th>JOGADOR</th><th>RATING</th><th>CONTA</th><th>AÇÕES</th></tr></thead><tbody>${Object.values(state.players).map(p=>`<tr><td>${esc(p.name)}</td><td>${p.rating} ${p.ratingVerified?'✓':''}</td><td>${badge(label[p.status])}</td><td><button class="text-btn" data-action="verify-rating" data-id="${p.id}">Verificar rating</button> <button class="text-btn" data-action="account-status" data-id="${p.id}">Alterar status</button></td></tr>`).join('')}</tbody></table></div><h2>Resultados e denúncias</h2>${state.games.filter(g=>g.status==='review').map(g=>`<div class="game-row"><span>${name(g.white)} × ${name(g.black)}<small>Vencedor: ${name(g.winner)} · ${g.reason}</small></span><button class="button small" data-game="${g.id}">Ver partida</button><button class="button primary small" data-action="approve-result" data-id="${g.id}">Homologar</button></div>`).join('')||'<div class="panel muted">Nenhum resultado aguardando homologação.</div>'}${state.reviews.filter(r=>r.type==='report'&&r.status==='open').map(r=>`<div class="panel"><b>Denúncia: ${name(r.user)}</b><p>${esc(r.reason)}</p><button class="button outline" data-action="close-review" data-id="${r.id}">Concluir revisão</button></div>`).join('')}<h2>Auditoria</h2><div class="panel audit">${state.audit.slice(-30).reverse().map(a=>`<div><small>${new Date(a.at).toLocaleString('pt-BR')}</small><b>${esc(a.action)}</b><code>${esc(JSON.stringify(a.detail))}</code></div>`).join('')||'Nenhuma decisão administrativa registrada.'}</div>`;}
function activeGame(){return practice||state.games.find(g=>g.id===gameId);}
function capturedTray(chess,color){const captures=capturedPieces(chess,color);return `<span class="captured-tray" role="group" aria-label="Peças capturadas pelas ${color==='w'?'brancas':'pretas'}" data-captured-by="${color}">${captures.map(p=>`<span class="captured-token" title="${{p:'Peão',n:'Cavalo',b:'Bispo',r:'Torre',q:'Dama'}[p.type]} capturado" data-captured-piece="${p.color+p.type}">${piece(p)}</span>`).join('')}</span>`;}
const seenResults=new Set(),practiceResultIds=new WeakMap();let resultCounter=0;
function showGameResult(){if(tab!=='board'||historyPly!==null&&historyPly!==activeGame()?.moves.length)return;const g=activeGame();if(!g)return;const outcome=gameOutcome(g,new Chess(g.fen),{viewer:actor?.id,practice:Boolean(practice)});if(!outcome)return;if(practice&&!practiceResultIds.has(g))practiceResultIds.set(g,++resultCounter);const key=(practice?'practice-'+practiceResultIds.get(g):g.id)+'-'+(g.rematches||0)+'-'+g.fen+'-'+(g.result||g.reason||'')+'-'+actor?.id;if(seenResults.has(key)||$('#modal').open)return;seenResults.add(key);modal(`<div class="result-card result-${outcome.kind}"><div class="result-emblem" aria-hidden="true">${outcome.kind==='win'?'♔':outcome.kind==='draw'?'½':'♚'}</div><h2>${esc(outcome.title)}</h2><p>${esc(outcome.detail)}</p>${g.status==='review'?'<small>Resultado em homologação. O prêmio aguarda as verificações da partida.</small>':''}<button class="button primary full" data-close>Ver tabuleiro</button></div>`);}
function boardView(){const g=activeGame();if(!g)return '<div class="empty">Partida não encontrada.</div>';const view=boardPosition(g,historyPly),chess=view.chess,own=g.white===actor?.id||g.black===actor?.id;const flip=boardFlipped!==Boolean(practice?g.computer&&g.humanColor==='b':g.black===actor?.id);const ranks=flip?[1,2,3,4,5,6,7,8]:[8,7,6,5,4,3,2,1],files=flip?'hgfedcba':'abcdefgh';const legal=selected?chess.moves({square:selected,verbose:true}).map(m=>m.to):[];let html=`<div class="board-heading"><div><div class="eyebrow">${practice?(g.computer?'CONTRA O COMPUTADOR · NÍVEL '+g.level:'TABULEIRO LIVRE · MESMO APARELHO'):'MESA '+esc(g.id.slice(0,8))}</div><h2>${practice?(g.computer?'Computador · '+LEVELS[g.level-1].name:'Aqueça seu jogo'):name(g.white)+' × '+name(g.black)}</h2></div><button class="button outline" data-tab="lobby">Voltar ao lobby</button></div><div class="board-controls" role="toolbar" aria-label="Controles da partida"><button class="button small outline" data-tab="lobby">← Voltar</button><button class="button small primary" data-action="${practice?(g.computer?'computer':'practice'):'new-online'}">Nova partida</button>${practice?`<button class="button small outline" data-action="undo" ${!g.moves.length?'disabled':''}>Voltar lance</button><button class="button small danger" data-action="computer-resign" ${g.status!=='playing'?'disabled':''}>Desistir</button>`:own&&g.status==='playing'?`<button class="button small danger" data-action="resign" data-id="${g.id}">Desistir</button>`:''}<button class="button small outline" data-action="flip-board" aria-label="Girar tabuleiro">Girar ↻</button><button class="button small outline" data-action="sound-toggle" aria-pressed="${soundEnabled()}">${soundEnabled()?'Som ligado':'Som desligado'}</button><label class="sound-volume">Volume <input id="sound-volume" aria-label="Volume dos efeitos" type="range" min="0" max="100" value="${Math.round(soundVolume()*100)}"></label><button class="button small outline" data-action="test-capture-sound">Testar som</button><label class="check capture-setting"><input id="capture-effects" type="checkbox" ${captureEffectsEnabled()?'checked':''}> Destruição</label></div><div class="game-announcement ${chess.isCheckmate()?'is-mate':chess.isCheck()?'is-check':''}" role="status" aria-live="polite">${!view.live?'Revisando lance '+view.count+' · volte ao último lance para jogar':mateAnnouncement(g,chess)||positionStatus(g,chess)|| (g.status==='pending'?'Aguardando aceite dos jogadores':thinking?'Computador pensando…':(chess.turn()==='w'?'Brancas':'Pretas')+' jogam')}</div>${trust.cameraPanel(practice?null:g)}<div class="board-layout ${practice?'practice-layout':''}"><section><div class="board-player">${boardAvatar(g,flip?'w':'b')}<b>${practice?(g.computer?(g.humanColor===(flip?'w':'b')?'Você':'Computador'):'Peças pretas'):name(flip?g.white:g.black)+' '+playerRating(flip?g.white:g.black,g.pool||poolFor(g.minutes,g.increment))}${capturedTray(chess,flip?'w':'b')}</b><span class="clock" id="clock-top" data-color="${flip?'w':'b'}"></span></div><div class="board" role="group" aria-label="Tabuleiro de xadrez">${ranks.map(rank=>[...files].map((file,i)=>{const square=file+rank,p=chess.get(square);return `<button class="square ${(file.charCodeAt(0)-97+rank)%2?'light':'dark'} ${selected===square?'picked':''} ${legal.includes(square)?'move-target':''} ${[view.last?.from,view.last?.to].includes(square)?'last-move':''} ${view.king===square?'king-check':''}" data-square="${square}" aria-label="${square}${p?' '+p.color+p.type:''}">${p?piece(p):''}${i===0?`<small class="rank-label">${rank}</small>`:''}${rank===ranks[7]?`<small class="file-label">${file}</small>`:''}</button>`;}).join('')).join('')}</div><div class="board-player">${boardAvatar(g,flip?'b':'w')}<b>${practice?(g.computer?(g.humanColor===(flip?'b':'w')?'Você':'Computador'):'Peças brancas'):name(flip?g.black:g.white)+' '+playerRating(flip?g.black:g.white,g.pool||poolFor(g.minutes,g.increment))}${capturedTray(chess,flip?'b':'w')}</b><span class="clock" id="clock-bottom" data-color="${flip?'b':'w'}"></span></div></section><aside class="board-side" aria-label="Lances e controles da partida">${!practice?`<article class="panel">${badge(practice?(g.computer?'Treino contra o computador':'Treino livre'):label[g.status],'green')}<h3>${positionStatus(g,chess)|| (thinking?'Computador pensando…':chess.isCheck()?'Xeque!':g.status==='playing'?(chess.turn()==='w'?'Brancas':'Pretas')+' jogam':g.status==='pending'?'Aguardando jogadores':g.status==='review'?'Resultado em homologação':'Partida concluída')}</h3>${!practice?`<div class="promo-line"><span>Total na mesa</span><b>${credits(g.stake*2)}</b></div><div class="promo-line"><span>Entrada por jogador</span><b>${credits(g.stake)}</b></div><div class="promo-line"><span>Prêmio líquido</span><b>${credits(g.stake*2-Math.floor(g.stake*2*g.feeBps/10000))}</b></div>${g.tournament?'<p class="muted">A premiação pertence ao torneio. Não há cobrança por rodada.</p>':''}${g.rematches?`<p>Revanche ${g.rematches} · cores invertidas</p>`:''}${g.automatedFairPlayHold&&own?'<p class="muted">Resultado em revisão de segurança. A liberação aguarda a conclusão.</p>':''}${g.winner?`<p>Vencedor: <b>${name(g.winner)}</b></p>`:''}${g.status==='pending'&&own?`<p>${g.accepted.map(name).join(', ')||'Nenhum jogador'} confirmou.</p><button class="button primary full" data-action="game-accept" data-id="${g.id}" ${g.accepted.includes(actor.id)?'disabled':''}>${g.accepted.includes(actor.id)?'Aguardando adversário':'Aceitar e abrir partida'}</button>${g.challenge&&Date.now()-g.createdAt>90000?`<button class="text-btn" data-action="game-abort" data-id="${g.id}">Cancelar por ausência</button>`:''}`:''}${!online&&g.status!=='finished'?`<button class="button outline full" data-action="switch-seat">Alternar jogador de teste</button><small class="muted">Simulação no mesmo navegador; não é um adversário online.</small>`:''}${g.status==='playing'&&own?`<button class="button outline small" data-action="claim-timeout" data-id="${g.id}">Reivindicar tempo esgotado</button><div class="button-row"><button class="button outline small" data-action="draw" data-id="${g.id}">${g.drawOffer&&g.drawOffer!==actor.id?'Aceitar empate':'Propor empate'}</button><button class="button danger small" data-action="resign" data-id="${g.id}">Desistir</button></div><button class="text-btn" data-action="report" data-id="${g.id}">Denunciar partida</button>`:''}`:`<p>${g.computer?'Você joga de '+(g.humanColor==='w'?'brancas':'pretas')+'. Nível '+g.level+' de 8. Sem apostas e sem alteração de rating.':'Jogue com as duas cores neste aparelho.'}</p><div class="button-row"><button class="button outline small" data-action="undo">Voltar lance</button><button class="button outline small" data-action="${g.computer?'computer':'practice'}">Nova partida</button></div>${g.computer&&g.status==='playing'?'<button class="text-btn" data-action="computer-resign">Desistir do treino</button>':''}`}</article>`:""}${!practice?ratingResult(g):''}<details class="panel moves-panel" ${movesExpanded?'open':''}><summary aria-label="Mostrar ou ocultar lances">Lances <span>${Math.ceil(g.moves.length/2)}</span><small>${movesExpanded?'Ocultar':'Mostrar'}</small></summary><div class="moves-content"><button class="text-btn" data-action="flip-board">Girar tabuleiro ↻</button><div class="history-controls" role="toolbar" aria-label="Navegar pelos lances"><button data-action="history-first" aria-label="Primeiro lance">|‹</button><button data-action="history-prev" aria-label="Lance anterior">‹</button><span>${view.count} / ${g.moves.length}</span><button data-action="history-next" aria-label="Próximo lance">›</button><button data-action="history-live" aria-label="Último lance">›|</button></div><div class="moves">${g.moves.map((m,i)=>`${i%2===0?`<small>${Math.floor(i/2)+1}.</small>`:''}<span>${esc(m)}</span>`).join('')||'<p class="muted">Aguardando o primeiro lance.</p>'}</div><button class="text-btn" data-action="export-pgn">Baixar PGN ↓</button>${practice?`<div class="side-game-actions"><button class="button outline small" data-action="undo" ${!g.moves.length?'disabled':''}>Voltar lance</button><button class="button danger small" data-action="computer-resign" ${g.status!=='playing'?'disabled':''}>Desistir ⚑</button></div>`:''}</div></details><label class="check privacy"><input type="checkbox" id="privacy-toggle"> Ocultar tabuleiro ao sair da tela</label></aside></div>`;const cut=html.indexOf('<div class="board-layout');const prefix=html.slice(0,cut);html=html.slice(cut);html=html.replace('<aside class="board-side" aria-label="Lances e controles da partida">','<aside class="board-side" aria-label="Lances e controles da partida">'+prefix);return html;}
function patchBoard(){const currentDisclosure=$('.moves-panel');if(currentDisclosure)movesExpanded=currentDisclosure.hasAttribute('open');const holder=document.createElement('div');holder.innerHTML=boardView();const current=$('.board'),fresh=holder.querySelector('.board');for(const [index,target]of [...fresh.querySelectorAll('[data-square]')].entries()){const square=current.querySelector(`[data-square="${target.dataset.square}"]`);if(square.innerHTML!==target.innerHTML)square.innerHTML=target.innerHTML;square.className=target.className;square.setAttribute('aria-label',target.getAttribute('aria-label'));if(current.children[index]!==square)current.insertBefore(square,current.children[index]||null);}for(const selector of ['.board-heading','.board-controls','.game-announcement','.camera-panel','.board-side']){const old=$('#content '+selector),next=holder.querySelector(selector);if(old&&next&&old.innerHTML!==next.innerHTML){const privacy=old.querySelector('#privacy-toggle')?.checked;old.innerHTML=next.innerHTML;if(privacy&&old.querySelector('#privacy-toggle'))old.querySelector('#privacy-toggle').checked=true;}if(old&&next)old.className=next.className;}const players=$('#content').querySelectorAll('.board-player');holder.querySelectorAll('.board-player').forEach((next,i)=>{players[i].innerHTML=next.innerHTML;});}
function mateAnnouncement(g,chess){if(!chess.isCheckmate())return '';const winner=chess.turn()==='w'?'b':'w';const ownColor=practice?(g.computer?g.humanColor:null):g.white===actor?.id?'w':g.black===actor?.id?'b':null;return `<strong class="mate-title">${ownColor?(winner===ownColor?'Vitória':'Derrota'):'Xeque-mate'}</strong><span>${ownColor?(winner===ownColor?'Você deu xeque-mate no seu oponente.':'Seu oponente deu xeque-mate.'):(winner==='w'?'Brancas':'Pretas')+' venceram por xeque-mate.'}</span>`;}
function captureEffectsEnabled(){const saved=localStorage.getItem('arena-capture-effects');return saved==='on'||saved!=='off'&&!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;}
function crumbleCapture(last,flipped){if(!last?.captured||!captureEffectsEnabled())return;const board=$('.board');if(!board)return;board.dataset.captureFeedback=String(Date.now());const square=last.flags.includes('e')?last.to[0]+last.from[1]:last.to;const file=square.charCodeAt(0)-97,rank=Number(square[1])-1;const effect=document.createElement('span');effect.className='capture-effect'+(localStorage.getItem('arena-capture-effects')==='on'?' force-motion':'');effect.setAttribute('aria-hidden','true');effect.dataset.captureSquare=square;effect.style.left=(flipped?7-file:file)*12.5+'%';effect.style.top=(flipped?rank:7-rank)*12.5+'%';const color=last.color==='w'?'b':'w';for(let i=0;i<9;i++){const shard=document.createElement('span');shard.className='piece capture-shard '+(color==='w'?'white-piece':'black-piece');shard.innerHTML=pieceSVG({color,type:last.captured});const x=i%3,y=Math.floor(i/3);shard.style.clipPath=`inset(${y*33.33}% ${100-(x+1)*33.33}% ${100-(y+1)*33.33}% ${x*33.33}%)`;shard.style.setProperty('--fall-x',((x-1)*35+(i%2?8:-8))+'%');shard.style.setProperty('--fall-y',(45+y*18)+'%');shard.style.setProperty('--fall-turn',((i-4)*12)+'deg');effect.append(shard);}board.append(effect);setTimeout(()=>effect.remove(),1450);}
function boardFeedback(){if(tab!=='board')return;const g=activeGame();if(!g)return;const key=practice?g:gameId;if(feedbackKey!==key){feedbackKey=key;feedbackMoves=g.moves.length;feedbackResult=g.status;historyPly=null;return;}if(g.moves.length!==feedbackMoves){historyPly=null;selected=null;if(g.moves.length>feedbackMoves){const view=boardPosition(g);const captureFlipped=boardFlipped!==Boolean(practice?g.computer&&g.humanColor==='b':g.black===actor.id);const unseenCapture=view.chess.history({verbose:true}).slice(feedbackMoves).findLast(m=>m.captured);if(unseenCapture)crumbleCapture(unseenCapture,captureFlipped);if(unseenCapture){playSound('capture');if(view.chess.isCheck()&&!view.chess.isCheckmate())playSound('check');}else playSound(moveSound(view.chess,view.last));const target=view.last&&$(`[data-square="${view.last.to}"] .piece`);const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;if(target?.animate&&!reduced){const flipped=boardFlipped!==Boolean(practice?g.computer&&g.humanColor==='b':g.black===actor.id);const dx=(view.last.from.charCodeAt(0)-view.last.to.charCodeAt(0))*(flipped?-1:1),dy=(Number(view.last.to[1])-Number(view.last.from[1]))*(flipped?-1:1);const size=$('.board [data-square]').getBoundingClientRect().width;target.animate([{transform:`translate(${dx*size}px,${dy*size}px)`},{transform:'translate(0,0)'}],{duration:280,easing:'cubic-bezier(.25,.1,.25,1)',fill:'both'});}}feedbackMoves=g.moves.length;}if(['review','finished'].includes(g.status)&&feedbackResult!==g.status&&g.moves.length===feedbackMoves)playSound('end');feedbackResult=g.status;}
function render(){document.body.classList.toggle('board-page',['board','setup'].includes(tab));document.body.classList.toggle('setup-page',tab==='setup');trust.check();if(tab==='setup'&&renderedTab==='setup'&&renderedActor===actor?.id&&setupRenderedHtml===setupHtml&&$('#content .setup-panel')){updateEntryPreview($('#content form'));return;}if(tab==='tournament-create'&&renderedTab===tab&&renderedActor===actor?.id&&$('#tournament-form')){updateTournamentPreview();return;}const g=tab==='board'&&activeGame();if(g&&(feedbackKey!==(practice?g:gameId)||g.moves.length!==feedbackMoves))historyPly=null;if(tab==='board'&&renderedTab==='board'&&renderedActor===actor?.id&&$('#content .board')){patchBoard();updateClocks();boardFeedback();showGameResult();return;}shell();$('#content').innerHTML=({lobby,tournaments,wallet,ranking,community,fairplay,setup:setupView,admin:administration,'my-games':myGamesPage,'tournament-create':tournamentCreateView,board:boardView}[tab]||lobby)();renderedTab=tab;renderedActor=actor?.id;if(tab==='setup'){setupRenderedHtml=setupHtml;updateSetupClocks($('#content form'));updateEntryPreview($('#content form'));}updateTournamentPreview();updateClocks();boardFeedback();showGameResult();}
function challengeForm(){modal(`<div class="eyebrow">UMA NOVA PARTIDA</div><h2>Criar desafio</h2><p>Entrada 0 cria uma partida casual grátis. Confira os valores antes de aceitar.</p><form id="challenge-form"><label>Entrada por jogador (créditos)<input name="stake" type="number" min="0" max="1000" step="1" value="10" required></label><label>Tempo por jogador<select name="minutes"><option value="1">1 minuto</option><option value="3">3 minutos</option><option value="5" selected>5 minutos</option><option value="10">10 minutos</option><option value="15">15 minutos</option></select></label><label>Incremento por lance<select name="increment">${[0,1,2,3,5,10,15,30].map(n=>`<option value="${n}">${n} segundos</option>`).join('')}</select></label><p class="muted">Taxa: ${state.settings.feeBps/100}%. Empate inicia revanche com o saldo reservado.</p><button class="button primary full">Criar e reservar entrada</button></form>`);}
function tournamentForm(){if(config.configured&&!online)return loginForm();if(!actor?.admin)return toast('Entre com a conta administradora para criar torneios.');$('#modal').close();tab='tournament-create';render();}
function tournamentCreateView(){if(!actor?.admin)return '<div class="panel">A criação de torneios é exclusiva da administração.</div>';return `<div class="page-heading"><div><div class="eyebrow">ORGANIZE SUA COMPETIÇÃO</div><h1>Novo torneio</h1><p>Configure a inscrição, a premiação e a capa antes de publicar.</p></div><button class="button outline" data-tab="tournaments">← Voltar aos torneios</button></div><form id="tournament-form" class="panel tournament-editor"><div id="tournament-error" role="alert"></div><label>Nome do torneio<input name="name" minlength="3" maxlength="80" placeholder="Ex.: Copa da Arena" required></label><h2>Capa do torneio</h2><div class="cover-picker" role="group" aria-label="Selecionar capa do torneio">${TOURNAMENT_COVERS.map((c,i)=>`<label class="cover-choice"><input type="radio" name="cover" value="${c.id}" ${i===0?'checked':''}><span class="cover-art cover-${c.id}" role="img" aria-label="${c.name}"></span><span>${c.name}</span></label>`).join('')}</div><label>Ou envie uma capa<input id="tournament-cover-file" type="file" accept="image/jpeg,image/png,image/webp"></label><input name="coverPath" type="hidden"><p id="tournament-cover-status" role="status"></p><img id="tournament-cover-preview" hidden alt="Prévia da capa enviada" style="max-width:360px;width:100%;border-radius:12px"><h2>Inscrição e prêmio</h2><div class="form-grid"><label>Vagas<input name="capacity" type="number" min="2" max="1024" step="1" value="200" required></label><label>Inscrição por jogador (créditos)<input name="entry" type="number" min="0" max="1000" step="0.01" value="0" required></label><label>Prêmio fixo ao campeão (créditos)<input name="prizeGuarantee" type="number" min="0" max="100000" step="0.01" value="0" required></label><div class="tournament-prize-preview" role="status"></div></div><p class="muted">O torneio inicia com pelo menos dois inscritos se a arrecadação superar o prêmio. Caso contrário, as inscrições são devolvidas.</p><h2>Partidas e inscrições</h2><div class="form-grid"><label>Início<input name="startsAt" type="datetime-local" value="${localDateTime(Date.now()+3600000)}" required></label><label>Tempo por jogador<select name="minutes">${[1,2,3,5,10,15,30,60].map(n=>`<option value="${n}" ${n===5?'selected':''}>${n} minutos</option>`).join('')}</select></label><label>Rating mínimo<input name="minRating" type="number" min="0" max="3500" value="0" required></label><label>Rating máximo<input name="maxRating" type="number" min="0" max="3500" value="2000" required></label></div><label class="check"><input name="verified" type="checkbox"> Exigir rating verificado</label><label class="check"><input name="camera" type="checkbox" ${config.trustConfigured?'':'disabled'}> Exigir câmera nas finais ${config.trustConfigured?'':'(fiscalização ainda não configurada)'}</label>${state.settings.sandraTournaments?`<label class="check"><input name="sandra" type="checkbox"> Inscrever Sandra - computador (saldo disponível: ${credits(state.players['arena-sandra']?.available)})</label>`:''}<button class="button primary" type="submit">Publicar torneio</button></form>`;}
function updateTournamentPreview(){const f=$('#tournament-form'),out=f?.querySelector('.tournament-prize-preview');if(!out)return;const entry=Math.round(Number(f.querySelector('[name=entry]').value||0)*100),capacity=Number(f.querySelector('[name=capacity]').value),prize=Math.round(Number(f.querySelector('[name=prizeGuarantee]').value||0)*100),pool=entry*capacity;out.textContent=`Prévia administrativa com ${capacity} inscrições: arrecadação ${credits(pool)} · prêmio fixo ${credits(prize)} · resultado ${credits(pool-prize)}. Valores reais dependem das inscrições confirmadas.`;}

function loginForm(){modal(`<h2>Entre na Arena</h2><p>${config.configured?'Acesse sua conta ou crie seu perfil para jogar online.':'O acesso online está indisponível no momento.'}</p><form id="login-form"><label>Nome público<input name="name" maxlength="32" value="Jogador" required></label><label>E-mail<input name="email" type="email" required autocomplete="email"></label><label>Senha<input name="password" type="password" minlength="10" required autocomplete="current-password"></label><button name="intent" value="login" class="button primary full" ${config.configured?'':'disabled'}>Entrar</button><button name="intent" value="signup" class="button outline full" ${config.configured?'':'disabled'}>Criar conta</button><p id="auth-error" class="auth-error" role="alert"></p></form><button class="text-btn" data-action="resend-email">Reenviar confirmação de e-mail</button><p class="muted">${config.configured?'Confirme seu e-mail antes de jogar.':'Enquanto isso, a demonstração permite testar partidas e torneios neste aparelho.'}</p>`);}
function playModes(){const queue=state.challenges.find(c=>c.creator===actor?.id&&c.matchmaking&&c.status==='open'&&(!c.expiresAt||c.expiresAt>Date.now()));return `${queue?`<div class="match-search" role="status"><span class="search-pulse"></span><span><b>Buscando adversário…</b><small>${queue.minutes} + ${queue.increment||0} · ${queue.stake?credits(queue.stake)+' de entrada':'grátis'} · aguardando outro jogador disponível</small></span><button class="button outline small" data-action="cancel-challenge" data-id="${queue.id}">Cancelar busca</button></div>`:''}<section class="play-modes" aria-label="Modos de jogo"><button class="mode-card" data-action="quick-match">${icon('users')}<span><b>Jogar online</b><small>Escolha seu tempo · grátis</small></span>${icon('arrow')}</button><button class="mode-card" data-action="computer">${icon('play')}<span><b>Contra o computador</b><small>8 níveis · escolha sua cor e ritmo</small></span>${icon('arrow')}</button><button class="mode-card" data-action="quick-match" data-mode="stake">${icon('wallet')}<span><b>Jogar com entrada</b><small>Mesmo valor de entrada · busca automática</small></span>${icon('arrow')}</button>${localStorage.getItem('arena-computer-v1')?'<button class="button outline" data-action="resume-computer">Retomar treino</button>':''}</section>`;}
async function startQuickSearch(mode='free',stake=0,minutes=5,increment=0,rated=true){if(!online)return loginForm();const ok=await send('quick_match',{minutes,increment,rated,stake,currency:'TEST'});if(!ok)return false;syncMatchDialog();return true;}
function syncMatchDialog(){if(!online)return;const dialog=$('#modal'),managed=dialog.dataset.match==='true';if(dialog.open&&!managed)return;const g=state.games.find(g=>g.status==='pending'&&[g.white,g.black].includes(actor.id));const q=state.challenges.find(c=>c.creator===actor.id&&c.matchmaking&&c.status==='open'&&(!c.expiresAt||c.expiresAt>Date.now()));if(g){const other=g.white===actor.id?g.black:g.white;modal(`<div class="matchup"><div class="eyebrow">ADVERSÁRIO ENCONTRADO</div><h2>${name(actor.id)} × ${name(other)}</h2><div class="matchup-players"><div>${avatar(actor.id)}<b>${name(actor.id)} ${playerRating(actor.id,g.pool)}</b><small>${g.accepted.includes(actor.id)?'Você aceitou':'Confirme o aceite'}</small></div><b>VS</b><div>${avatar(other)}<b>${name(other)} ${playerRating(other,g.pool)}</b><small>${g.accepted.includes(other)?'Aceitou':'Aguardando aceite'}</small></div></div>${g.stake?`<p>Entrada por jogador: <b>${credits(g.stake)}</b><br>Total reservado: <b>${credits(g.stake*2)}</b><br>Prêmio líquido: ${credits(g.stake*2-Math.floor(g.stake*2*g.feeBps/10000))}</p>`:`<p>Partida gratuita · ${g.minutes} + ${g.increment||0}${g.rated===false?' · Sem rating':' · Com rating'}</p>`}<button class="button primary full" data-action="game-accept" data-id="${g.id}" ${g.accepted.includes(actor.id)?'disabled':''}>${g.accepted.includes(actor.id)?'Aguardando adversário…':'Aceitar partida'}</button></div>`);dialog.dataset.match='true';return;}if(q){modal(`<div class="matchup"><h2>Buscando adversário…</h2><div class="search-spinner" aria-hidden="true"></div><p>Procurando jogador disponível com rating próximo.</p><p>${q.stake?`Entrada: ${credits(q.stake)}<br>Saldo reservado durante a busca.`:`Partida gratuita · ${q.minutes} + ${q.increment||0}${q.rated===false?' · Sem rating':' · Com rating'}`}</p><button class="button outline full" data-action="cancel-challenge" data-id="${q.id}">Cancelar busca</button></div>`);dialog.dataset.match='true';return;}const playing=state.games.find(g=>g.status==='playing'&&[g.white,g.black].includes(actor.id));if(managed){dialog.close();dialog.dataset.match='false';if(playing){gameId=playing.id;practice=null;tab='board';selected=null;render();}}}
function configure(html){$('#modal').close();setupHtml=html;tab='setup';render();}
function previewBoard(){const c=new Chess();return `<div class="board" role="group" aria-label="Tabuleiro de prévia">${[8,7,6,5,4,3,2,1].map(rank=>[...'abcdefgh'].map(file=>`<div class="square ${(file.charCodeAt(0)-97+rank)%2?'light':'dark'}">${c.get(file+rank)?piece(c.get(file+rank)):''}${file==='a'?`<small class="rank-label">${rank}</small>`:''}${rank===1?`<small class="file-label">${file}</small>`:''}</div>`).join('')).join('')}</div>`;}
function setupView(){return `<div class="setup-layout"><section><div class="board-player"><span class="avatar">♟</span><b>Adversário</b><span class="clock setup-clock">05:00</span></div>${previewBoard()}<div class="board-player">${avatar(actor?.id)}<b>${state.players[actor?.id]?name(actor.id):'Você'}</b><span class="clock setup-clock">05:00</span></div></section><aside class="setup-panel panel" aria-label="Configuração da partida"><nav class="setup-tabs"><button class="button small outline" data-action="quick-match">Online</button><button class="button small outline" data-action="computer">Computador</button><button class="button small outline" data-action="quick-match" data-mode="stake">Com entrada</button><button class="text-btn" data-tab="lobby">← Voltar</button></nav>${setupHtml}</aside></div>`;}
function updateSetupClocks(form){if(tab!=='setup'||!form)return;const minutes=Number(form.querySelector('[name=minutes]')?.value||0),increment=Number(form.querySelector('[name=increment]')?.value||0);document.querySelectorAll('.setup-clock').forEach(el=>el.textContent=minutes?String(minutes).padStart(2,'0')+':00'+(increment?' + '+increment:''):'∞');}
const TIME_PRESETS=[['Bullet',[[1,0],[1,1],[2,1]]],['Blitz',[[3,0],[3,2],[5,0]]],['Rápida',[[10,0],[10,5],[15,10]]]];
function timePicker(){return `<div class="time-picker" aria-label="Controles de tempo">${TIME_PRESETS.map(([group,times])=>`<div><h3>${group}</h3><div class="time-options">${times.map(([minutes,increment])=>`<button type="button" data-time-control="${minutes},${increment}" aria-pressed="false">${increment?minutes+' + '+increment:minutes+' min'}</button>`).join('')}</div></div>`).join('')}</div>`;}
function updateEntryPreview(form){const output=form?.querySelector('.entry-preview');if(!output)return;const entry=Math.max(0,Math.round(Number(form.querySelector('[name=stake]')?.value||0)*100)),pool=entry*2,fee=state.settings.feeBps;output.textContent=`Comissão da plataforma: ${fee/100}% sobre o total da mesa. Prêmio líquido: ${credits(pool-Math.floor(pool*fee/10000))}.`;}
function quickMatchForm(mode='free'){configure(`<h2>${mode==='stake'?'Jogar com entrada':'Jogar online'}</h2><p>Escolha o ritmo. A busca encontra alguém com o mesmo tempo, incremento e entrada.</p><form id="quick-form"><input type="hidden" name="mode" value="${mode}">${timePicker()}<details><summary>Tempo personalizado</summary><div class="form-grid"><label>Minutos<select name="minutes">${[1,2,3,5,10,15,30,60].map(n=>`<option value="${n}" ${n===5?'selected':''}>${n}</option>`).join('')}</select></label><label>Incremento<select name="increment">${[0,1,2,3,5,10,15,30].map(n=>`<option>${n}</option>`).join('')}</select></label></div></details><label class="check"><input type="checkbox" name="rated" checked> Com rating</label>${state.settings.sandraChallenges?'<label>Adversário<select name="opponent"><option value="human">Buscar jogador humano</option><option value="sandra">Sandra - computador</option></select></label><label class="check"><input type="checkbox" name="botConsent"> Ao escolher Sandra, aceito enfrentar um computador, sem alterar meu rating.</label>':''}${mode==='stake'?'<label>Entrada por jogador (créditos)<input name="stake" type="number" min="1" max="1000" value="10" required></label><p>Valores reservados até o resultado.</p><p class="entry-preview" aria-live="polite">Comissão da plataforma: Carregando comissão e prêmio…</p>':''}<button class="button primary full">Começar partida</button></form>`);}

function profileForm(){if(config.configured&&!online)return loginForm();const p=state.players[actor.id];profilePhoto=null;modal(`<h2>Seu perfil</h2><div class="profile-photo">${avatar(actor.id)}<div><b>${name(actor.id)}</b><p>Sua foto será pública no perfil e nas partidas.</p></div></div><form id="profile-form"><label>Nome de exibição<input name="name" minlength="2" maxlength="32" value="${name(actor.id)}" required></label><label>Nome de usuário único<input name="username" pattern="[a-zA-Z0-9_]{3,24}" minlength="3" maxlength="24" value="${esc(userHandle(p))}" required></label><label>Foto de perfil<input id="avatar-file" type="file" accept="image/jpeg,image/png,image/webp" ${online?'':'disabled'}></label><p id="avatar-status" role="status">${online?'JPEG, PNG ou WebP. Recorte central automático. Máximo 5 MB.':'Fotos ficam disponíveis ao entrar na conta online.'}</p><button class="text-btn" type="button" data-action="avatar-remove">Remover foto</button><div class="rating-pills">${POOLS.map(pool=>`<span>${{bullet:'Bullet',blitz:'Blitz',rapid:'Rápido',classical:'Clássico'}[pool]} ${playerRating(actor.id,pool)}</span>`).join('')}</div><button class="button primary full">Salvar perfil</button></form><button class="button outline full" data-action="verify-identity">Verificar CPF e identidade</button>`);}
function socialActions(uid){if(uid===actor?.id)return '<button class="button small" data-action="edit-profile">Editar perfil</button>';if(!state.players[actor?.id])return '<button class="button small" data-action="login">Entre para interagir</button>';const block=(state.blocks||[]).some(b=>b.to===uid);if(block)return `<button class="button outline small" data-action="unblock-user" data-id="${uid}">Desbloquear</button>`;const f=(state.friendships||[]).find(f=>related(f,actor.id,uid)&&['accepted','pending'].includes(f.status));return `<div class="social-actions"><button class="button small primary" data-action="invite-player" data-id="${uid}">Convidar para jogar</button>${f?.status==='accepted'?`<button class="button small outline" data-action="friend-remove" data-id="${f.id}">Remover amizade</button>`:f?.status==='pending'?f.to===actor.id?`<button class="button small" data-action="friend-accept" data-id="${f.id}">Aceitar amizade</button><button class="button small outline" data-action="friend-reject" data-id="${f.id}">Recusar</button>`:`<button class="button small outline" data-action="friend-remove" data-id="${f.id}">Cancelar solicitação</button>`:`<button class="button small outline" data-action="friend-request" data-id="${uid}">Adicionar amigo</button>`}<button class="text-btn" data-action="block-user" data-id="${uid}">Bloquear</button></div>`;}
function community(){const me=actor?.id,friendIds=(state.friendships||[]).filter(f=>f.status==='accepted').map(f=>f.from===me?f.to:f.from),requests=(state.friendships||[]).filter(f=>f.status==='pending'),invites=state.challenges.filter(c=>c.target&&[c.creator,c.target].includes(me)&&c.status==='open'&&(!c.expiresAt||c.expiresAt>Date.now()));const list=Object.values(state.players).filter(p=>p.status==='active'&&(!peopleQuery||(p.name+' '+userHandle(p)).toLocaleLowerCase('pt-BR').includes(peopleQuery.toLocaleLowerCase('pt-BR')))&&(peopleFilter==='all'||peopleFilter==='online'&&isOnline(p)||peopleFilter==='friends'&&friendIds.includes(p.id)));return `<div class="page-heading"><div><div class="eyebrow">SUA COMUNIDADE DE XADREZ</div><h1>Jogadores e amizades</h1><p>Encontre pelo nome ou @usuário, adicione amigos e convide para sua mesa.</p></div><button class="button outline" data-action="edit-profile">Editar meu perfil</button></div><form id="people-search" class="people-search"><input name="query" placeholder="Buscar nome ou @usuário" value="${esc(peopleQuery)}" maxlength="60"><button class="button primary">Buscar jogador</button></form><div class="filters">${[['all','Todos'],['online','Online agora'],['friends','Meus amigos · '+friendIds.length]].map(([v,l])=>`<button data-people-filter="${v}" class="${peopleFilter===v?'selected':''}">${l}</button>`).join('')}</div>${requests.length?`<h2>Solicitações de amizade</h2><div class="community-grid">${requests.map(f=>{const uid=f.from===me?f.to:f.from;return `<article class="panel"><div class="player-cell">${avatar(uid)}${playerLink(uid)}</div><p>${f.to===me?'Quer ser seu amigo':'Solicitação enviada'}</p>${socialActions(uid)}</article>`;}).join('')}</div>`:''}${invites.length?`<h2>Convites para jogar</h2>${invites.map(c=>`<article class="game-row"><span>${playerLink(c.creator===me?c.target:c.creator)}<small>${c.minutes} + ${c.increment||0} · ${c.stake?credits(c.stake)+' por jogador · taxa '+c.feeBps/100+'%':'Grátis'} · expira em até 5 minutos</small></span>${c.target===me?`<button class="button primary small" data-action="accept-challenge" data-id="${c.id}">Ver convite e aceitar</button><button class="button outline small" data-action="decline-invite" data-id="${c.id}">Recusar</button>`:`<button class="button outline small" data-action="cancel-challenge" data-id="${c.id}">Cancelar convite</button>`}</article>`).join('')}`:''}<h2>${peopleFilter==='friends'?'Seus amigos':'Jogadores'} · ${list.length}</h2><div class="community-grid">${list.map(p=>`<article class="panel player-card"><div class="player-cell">${avatar(p.id)}<span>${playerLink(p.id)}<small>@${esc(userHandle(p))} · <span class="${isOnline(p)?'online-label':''}">${isOnline(p)?'Online':'Offline'}</span></small></span></div><div class="rating-pills">${POOLS.map(pool=>`<span>${{bullet:'Bullet',blitz:'Blitz',rapid:'Rápido',classical:'Clássico'}[pool]} ${playerRating(p.id,pool)}</span>`).join('')}</div>${socialActions(p.id)}</article>`).join('')||'<div class="panel empty">Nenhum jogador encontrado. Tente outro nome ou filtro.</div>'}</div>`;}
function playerProfile(uid){const p=state.players[uid];if(!p)return;modal(`<div class="public-profile"><div class="profile-photo">${avatar(uid)}<div><h2>${name(uid)}</h2><p>@${esc(userHandle(p))} · ${isOnline(p)?'Online agora':'Offline'}</p></div></div><div class="rating-pills">${POOLS.map(pool=>`<span>${{bullet:'Bullet',blitz:'Blitz',rapid:'Rápido',classical:'Clássico'}[pool]} ${playerRating(uid,pool)}</span>`).join('')}</div><p>${p.wins||0} vitórias · ${p.losses||0} derrotas</p>${socialActions(uid)}<h3>Partidas recentes</h3>${state.games.filter(g=>[g.white,g.black].includes(uid)&&['playing','finished','review'].includes(g.status)).slice(-8).reverse().map(g=>`<button class="game-row" data-game="${g.id}"><span>${name(g.white)} × ${name(g.black)}<small>${g.minutes} + ${g.increment||0} · ${label[g.status]}</small></span><b>${g.winner?name(g.winner)+' venceu':'Assistir'}</b></button>`).join('')||'<p>Nenhuma partida concluída ou em andamento.</p>'}</div>`);}
function invitePlayer(uid){if(config.configured&&!online)return loginForm();const p=state.players[uid];modal(`<h2>Convidar ${name(uid)}</h2><p>@${esc(userHandle(p))} · o convite será enviado apenas a este jogador.</p><form id="direct-invite" data-user="${uid}"><label>Tempo por jogador<select name="minutes">${[1,3,5,10,15,30].map(n=>`<option value="${n}" ${n===5?'selected':''}>${n} minutos</option>`).join('')}</select></label><label>Incremento<select name="increment">${[0,1,2,3,5,10].map(n=>`<option>${n}</option>`).join('')}</select></label><label>Entrada por jogador (0 = grátis)<input name="stake" type="number" min="0" max="1000" value="0" required></label><p>Com entrada: taxa ${state.settings.feeBps/100}%. Valores serão exibidos antes do aceite.</p><button class="button primary full">Enviar convite</button></form>`);}
async function prepareAvatar(file){if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('Escolha JPEG, PNG ou WebP de até 5 MB.');const bitmap=await createImageBitmap(file);try{const canvas=document.createElement('canvas');canvas.width=canvas.height=128;const ctx=canvas.getContext('2d');ctx.fillStyle='#22252a';ctx.fillRect(0,0,128,128);const size=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-size)/2,(bitmap.height-size)/2,size,size,0,0,128,128);return canvas.toDataURL('image/jpeg',.8);}finally{bitmap.close();}}
async function uploadProfilePhoto(){if(profilePhoto===null)return true;if(profilePhoto==='remove')return send('profile_update',{avatarPath:null});const response=await fetch('/api/index?action=avatar',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${session.access_token}`},body:JSON.stringify({image:profilePhoto})});const data=await response.json();if(!response.ok)throw Error(data.error||'Não foi possível salvar a foto.');state=data.state;actor=data.actor;profilePhoto=null;render();return true;}
function computerForm(){configure(`<h2>Jogar contra o computador</h2><p>Escolha entre oito níveis, defina o ritmo e pratique seus próximos lances. Estas partidas não alteram seu rating.</p><form id="computer-form">${timePicker()}<label>Dificuldade<select name="level">${LEVELS.map((l,i)=>`<option value="${i+1}" ${i===2?'selected':''}>Nível ${i+1} · ${l.name}</option>`).join('')}</select></label><label>Suas peças<select name="color"><option value="w">Brancas</option><option value="b">Pretas</option><option value="random">Aleatórias</option></select></label><label>Tempo por jogador<select name="minutes"><option value="0">Sem relógio</option>${[1,2,3,5,10,15,30,60].map(n=>`<option value="${n}">${n} minutos</option>`).join('')}</select></label><label>Incremento por lance<select name="increment">${[0,1,2,3,5,10].map(n=>`<option>${n}</option>`).join('')}</select></label><button class="button primary full">Começar partida</button></form>`);}
function startComputer(d){movesExpanded=true;cancelComputer();boardFlipped=false;const color=d.get('color'),minutes=Number(d.get('minutes'));practice={computer:true,level:Number(d.get('level')),humanColor:color==='random'?(Math.random()<.5?'w':'b'):color,fen:new Chess().fen(),moves:[],pgn:'',status:'playing',white:'demo-you',black:'demo-you',minutes,increment:Number(d.get('increment')),whiteMs:minutes*60000,blackMs:minutes*60000,lastMoveAt:Date.now()};selected=null;tab='board';savePractice();render();computerTurn();}
function authMessage(error){return ({email_not_confirmed:'Confirme seu e-mail antes de entrar. Procure a mensagem de confirmação na caixa de entrada ou no spam.',invalid_credentials:'E-mail ou senha incorretos.',over_email_send_rate_limit:'Aguarde alguns minutos antes de solicitar outro e-mail.',user_already_exists:'Esta conta já existe. Confirme seu e-mail e clique em Entrar.',email_address_not_authorized:'O serviço de e-mail ainda está em configuração. Entre em contato com a administração.'})[error.code]||'Não foi possível concluir. '+error.message;}
function confirmationNotice(email){modal(`<div class="eyebrow">FALTA SÓ UM PASSO</div><h2>Confirme seu e-mail</h2><p>Enviamos um link de confirmação para <strong>${esc(email)}</strong>.</p><p>Abra a mensagem, clique em <strong>Confirmar e-mail</strong> e volte à Arena para entrar. No e-mail padrão, o botão pode aparecer como <strong>Confirm your email address</strong>.</p><div class="panel"><b>Não encontrou?</b><p>Confira as pastas Spam e Promoções. O remetente atual é Supabase Auth. Não é necessário cadastrar novamente.</p></div><button class="button primary full" data-action="back-login">Já confirmei · entrar</button><button class="text-btn" data-action="resend-email">Reenviar confirmação</button>`);sessionStorage.setItem('arena-confirm-email',email);}
async function resendEmail(){if(!client)return;const email=$('#login-form input[name="email"]')?.value||sessionStorage.getItem('arena-confirm-email');if(!email)return toast('Informe seu e-mail no formulário antes de solicitar o reenvio.');const {error}=await client.auth.resend({type:'signup',email,options:{emailRedirectTo:location.origin+'/'}});if(error)return toast(authMessage(error));confirmationNotice(email);toast('Solicitação enviada. Confira também a pasta de spam.');}
async function squareClick(square){if(historyPly!==null&&historyPly!==activeGame()?.moves.length)return toast('Volte ao último lance para jogar.');const g=activeGame();if(!practice&&g&&![g.white,g.black].includes(actor?.id))return;if(!g||g.status!=='playing'||(practice?.computer&&(thinking||new Chess(g.fen).turn()!==g.humanColor)))return;const chess=new Chess(g.fen);if(selected===square){selected=null;render();return;}if(selected){const moves=chess.moves({square:selected,verbose:true}).filter(m=>m.to===square);if(moves.length){if(moves.some(m=>m.promotion)){modal(`<h2>Promover peão</h2><div class="promotion">${['q','r','b','n'].map(p=>`<button aria-label="Promover para ${{q:'Dama',r:'Torre',b:'Bispo',n:'Cavalo'}[p]}" data-promote="${p}" data-from="${selected}" data-to="${square}">${piece({color:chess.turn(),type:p})}<small>${{q:'Dama',r:'Torre',b:'Bispo',n:'Cavalo'}[p]}</small></button>`).join('')}</div>`);return;}return playMove(selected,square);}}const p=chess.get(square);selected=p?.color===chess.turn()?square:null;render();}
function savePractice(){if(practice?.computer)localStorage.setItem('arena-computer-v1',JSON.stringify(practice));}
function finishPractice(c){if(c.isGameOver()){practice.status='finished';practice.result=c.isCheckmate()?(c.turn()===practice.humanColor?'Xeque-mate · Computador venceu':'Xeque-mate · Você venceu!'):'Empate por '+drawReason(c)+' · inicie uma nova partida';}}
function commitPracticeMove(move){const c=new Chess();for(const m of practice.moves)c.move(m);if(practice.minutes){const color=c.turn(),key=color==='w'?'whiteMs':'blackMs';practice[key]-=Math.max(0,Date.now()-practice.lastMoveAt);if(practice[key]<=0){practice.status='finished';practice.result='Tempo esgotado · '+(color===practice.humanColor?'Computador venceu':'Você venceu');savePractice();render();return;}practice[key]+=(practice.increment||0)*1000;}const m=c.move(move);practice.moves.push(m.san);practice.fen=c.fen();practice.pgn=c.pgn();practice.lastMoveAt=Date.now();selected=null;finishPractice(c);savePractice();render();}
function cancelComputer(){engineGeneration++;thinking=false;computerWorker?.terminate();computerWorker=null;}
function computerTurn(){if(!practice?.computer||practice.status!=='playing'||new Chess(practice.fen).turn()===practice.humanColor||thinking)return;thinking=true;const id=++engineGeneration,startedAt=Date.now();try{computerWorker??=new Worker('/computer-worker.js',{type:'module'});computerWorker.onmessage=e=>{setTimeout(()=>{if(e.data.id!==engineGeneration||!practice?.computer||practice.status!=='playing')return;thinking=false;if(e.data.error){toast(e.data.error);render();return;}try{commitPracticeMove(e.data.move);}catch{toast('Não foi possível executar o lance do computador.');}},Math.max(0,360-(Date.now()-startedAt)));};computerWorker.onerror=()=>{cancelComputer();toast('Não foi possível iniciar o computador. Tente novamente.');render();};computerWorker.postMessage({id,fen:practice.fen,level:practice.level});render();}catch{cancelComputer();toast('Este navegador não conseguiu iniciar o computador.');}}

async function playMove(from,to,promotion='q'){if(practice){try{commitPracticeMove({from,to,promotion});computerTurn();}catch{toast('Lance inválido.');}}else await send('move',{id:gameId,from,to,promotion,ply:activeGame().moves.length});}
function updateClocks(){if(tab!=='board')return;const g=activeGame();if(!g)return;if(practice?.computer&&g.minutes&&g.status==='playing'){const color=new Chess(g.fen).turn();if(g[color==='w'?'whiteMs':'blackMs']-(Date.now()-g.lastMoveAt)<=0){cancelComputer();g.status='finished';g.result='Tempo esgotado · '+(color===g.humanColor?'Computador venceu':'Você venceu');savePractice();render();return;}}let turn=new Chess(g.fen).turn();for(const el of document.querySelectorAll('[data-color]')){const color=el.dataset.color;let ms=g[color==='w'?'whiteMs':'blackMs'];if((!practice||g.minutes)&&g.status==='playing'&&turn===color)ms-=Math.max(0,Date.now()-g.lastMoveAt);ms=Math.max(0,ms);el.textContent=practice&&!g.minutes?'∞':`${Math.floor(ms/60000).toString().padStart(2,'0')}:${Math.floor(ms%60000/1000).toString().padStart(2,'0')}`;el.classList.toggle('ticking',g.status==='playing'&&turn===color);}}
