let lastStatePoll=0,statePollPending=false;
setInterval(async()=>{if(!online||document.hidden||busy||statePollPending)return;const fast=tab==='board'&&!practice&&state.games.some(g=>g.id===gameId&&g.bot==='arena-sandra'&&['pending','playing'].includes(g.status));if(Date.now()-lastStatePoll<(fast?650:2000))return;lastStatePoll=Date.now();statePollPending=true;try{if(Date.now()-lastPresence>30000){lastPresence=Date.now();await api({id:crypto.randomUUID(),type:'presence',payload:{}});}const result=await api();if(busy||($('#modal').open&&$('#modal').dataset.match!=='true'))return;if(!result.actor){session=null;online=false;state=result.state;render();return;}const old=JSON.stringify(state);const oldSocial=socialCount(state,actor.id);if(socialCount(result.state,actor.id)>oldSocial)toast('Novo convite ou solicitação de amizade. Abra Jogadores.');const added=result.state.tournaments.filter(t=>!state.tournaments.some(old=>old.id===t.id));if(added.length)toast(`${added.length} novo${added.length>1?'s campeonatos':' campeonato'} ${added.length>1?'disponíveis':'disponível'}. Confira Torneios.`);state=result.state;actor=result.actor;syncMatchDialog();if(JSON.stringify(state)!==old)render();const g=state.games.find(g=>g.id===gameId);if(tab==='board'&&!practice&&g?.status==='playing'){const color=new Chess(g.fen).turn();if(g[color==='w'?'whiteMs':'blackMs']-(Date.now()-g.lastMoveAt)<=0)await send('timeout',{id:g.id});}}catch{}finally{statePollPending=false;}},650);
async function enterOnline(currentSession,displayName){session=currentSession;online=true;const result=await api();state=result.state;actor=result.actor;if(!state.players[actor.id])await send('register',{name:displayName||session.user?.user_metadata?.display_name||'Jogador'});render();}
async function boot(){const route=location.hash.slice(1);if(['lobby','tournaments','wallet','fairplay','ranking','community','my-games'].includes(route))tab=route;loadDemo();try{config=await fetch('/api/index?action=config').then(r=>r.json());if(config.configured){client=createClient(config.supabaseUrl,config.publishableKey);session=(await client.auth.getSession()).data.session;if(session)await enterOnline(session);else state=(await api()).state;client.auth.onAuthStateChange((event,newSession)=>{if(['SIGNED_IN','TOKEN_REFRESHED'].includes(event)&&newSession){session=newSession;setTimeout(()=>enterOnline(newSession).catch(()=>toast('Não foi possível carregar sua conta. Tente entrar novamente.')),0);}if(event==='SIGNED_OUT'){session=null;loadDemo();api().then(r=>{state=r.state;render();}).catch(()=>render());}});}}catch{}render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}
trust.startSignals();boot();

async function saveSandraAvatar(remove=false){if(!online||!actor?.admin)throw Error('Acesso exclusivo da administração.');if(busy)throw Error('Aguarde a operação atual.');busy=true;try{const data=await trustRequest('sandra-avatar',remove?{remove:true}:{image:sandraPhoto});sandraPhoto=null;return data;}finally{busy=false;}}
document.addEventListener('change',async e=>{if(e.target.id!=='sandra-avatar-file')return;const submit=$('#sandra-avatar-form button[type=submit]');if(submit)submit.disabled=true;try{sandraPhoto=await prepareAvatar(e.target.files[0]);$('#sandra-avatar-status').textContent='Imagem pronta. Clique em Salvar avatar da Sandra.';const preview=$('#sandra-avatar-form .avatar');if(preview)preview.innerHTML=`<img src="${sandraPhoto}" alt="Prévia do avatar da Sandra">`;}catch(error){sandraPhoto=null;$('#sandra-avatar-status').textContent=error.message;}finally{if(submit)submit.disabled=false;}});

document.addEventListener('click',async e=>{const b=e.target.closest('[data-action="reenter-tournament"]');if(!b)return;b.disabled=true;try{await send('tournament_reenter',{id:b.dataset.id});}finally{b.disabled=false;}});

document.addEventListener('change',async e=>{if(e.target.name==='cover'){const path=$('#tournament-form [name=coverPath]');if(path)path.value='';const preview=$('#tournament-cover-preview');if(preview)preview.hidden=true;}if(e.target.id!=='tournament-cover-file')return;const f=$('#tournament-form'),button=f.querySelector('[type=submit]'),status=$('#tournament-cover-status');button.disabled=true;try{if(!online)throw Error('Entre com a conta administrativa para enviar uma capa.');const file=e.target.files[0];if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('Escolha JPEG, PNG ou WebP de até 5 MB.');status.textContent='Preparando capa…';const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,512/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let quality=.85,image=canvas.toDataURL('image/jpeg',quality);while(image.length>43000&&quality>.2){quality-=.1;image=canvas.toDataURL('image/jpeg',quality);}if(image.length>43000)throw Error('Escolha uma imagem menos detalhada.');const result=await trustRequest('tournament-cover',{image});f.querySelector('[name=coverPath]').value=result.coverPath;const preview=$('#tournament-cover-preview');preview.src=image;preview.hidden=false;status.textContent='Capa enviada. Será publicada ao criar o torneio.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});
